import React from 'react';
import { connect } from 'react-redux';
import { Input } from 'reactstrap';
import moment from 'moment';
import CustomButton from 'components/CustomButton';
import FilterSelect from 'views/admin/Common/FilterSelect';
import StatTile from 'views/admin/Common/StatTile';
import MuiTable from 'views/admin/Common/MuiTable.jsx';
import BillingFormModal from 'views/admin/Students/components/BillingFormModal.jsx';
import BillTypeTag from 'views/admin/Students/components/BillTypeTag.jsx';
import BillReceiptLinks from 'views/admin/Common/BillReceiptLinks.jsx';
import {
  fetchAllStudentBillingsService,
  addStudentBillingService,
  updateStudentBillingService,
} from 'actions/admin/billing';
import { fetchSchoolStudentsPlainService } from 'actions/admin/students';
import { showToast } from 'actions/admin/auth';
import { formatMoney, getGlobalCurrentBatchUtils } from 'utils/commonFunc';
import { formStudentName } from 'config/constants';
import { store } from 'index';
import colors from 'config/colors';

const tableHeaders = ['Payer', 'Bill', 'Type', 'Amount', 'Status', 'Due Date', 'Receipt'];
const bodyColumns = [
  'payerCell',
  'billCell',
  'typeLabel',
  'amountLabel',
  'statusLabel',
  'dueDateLabel',
  'receiptLabel',
];

const subText = { fontSize: 12, color: '#9a9a9a', marginTop: 1 };
const niceEnum = value =>
  value
    ? String(value)
        .toLowerCase()
        .split('_')
        .map(word => word.charAt(0).toUpperCase() + word.slice(1))
        .join(' ')
    : '--';

class BillingsPage extends React.Component {
  constructor() {
    super();
    this.state = {
      schoolId: null,
      isFetching: false,
      isSaving: false,
      isModalOpen: false,
      editingBill: null,
      searchText: '',
      // filters: who pays (student / other), the kind of bill, and whether it is paid
      filterPayer: '',
      filterType: '',
      filterStatus: '',
      // Every student of the school's current batch (not just a page) - feeds both the picker in
      // the Add Bill modal and the name/register number lookup for the list rows.
      students: [],
      isStudentsFetching: false,
    };
  }

  componentDidMount() {
    const globalSchool = this.props.loggedUserSchool;
    if (globalSchool) {
      this.setState({ schoolId: globalSchool }, () => {
        this.fetchBillings();
        this.fetchStudents();
      });
    }
  }

  fetchBillings = () => {
    this.setState({ isFetching: true });
    this.props
      .fetchAllStudentBillings({
        schoolId: this.state.schoolId,
        token: this.props.loggedUserToken,
      })
      .then(() => this.setState({ isFetching: false }));
  };

  fetchStudents = () => {
    const { batchId } = getGlobalCurrentBatchUtils();
    this.setState({ isStudentsFetching: true });
    fetchSchoolStudentsPlainService(this.state.schoolId, batchId, this.props.loggedUserToken)
      .then(data => this.setState({ students: data?.content || [], isStudentsFetching: false }))
      .catch(err => {
        console.error('err-fetchSchoolStudentsPlainService', err);
        this.setState({ isStudentsFetching: false });
      });
  };

  openAddBill = () => this.setState({ isModalOpen: true, editingBill: null });

  closeModal = () => this.setState({ isModalOpen: false, editingBill: null });

  showWarning = (message, type) => store.dispatch(showToast(message, type));

  submitCreateBill = postData => {
    this.setState({ isSaving: true });
    return this.props
      .createBilling({
        ...postData,
        schoolId: this.state.schoolId,
        token: this.props.loggedUserToken,
      })
      .then(() => {
        this.setState({ isSaving: false });
        this.fetchBillings();
      })
      .catch(err => {
        this.setState({ isSaving: false });
        throw err;
      });
  };

  submitUpdateBill = (studentCustomBillId, postData) => {
    this.setState({ isSaving: true });
    return this.props
      .updateBilling({ ...postData, studentCustomBillId, token: this.props.loggedUserToken })
      .then(() => {
        this.setState({ isSaving: false });
        this.fetchBillings();
      })
      .catch(err => {
        this.setState({ isSaving: false });
        throw err;
      });
  };

  render() {
    const {
      isFetching,
      isSaving,
      isModalOpen,
      editingBill,
      searchText,
      students,
      isStudentsFetching,
      filterPayer,
      filterType,
      filterStatus,
    } = this.state;
    const { allStudentBillings } = this.props;
    const studentOptions = students.map(el => ({
      value: el.studentId,
      label: `${formStudentName(el)}${el.registerNumber ? ` (${el.registerNumber})` : ''}`,
    }));
    // StudentCustomBillDto only carries studentId, not the student's name/reg number - the
    // backend doesn't enrich it, so resolve those against the batch student list already
    // fetched for the picker.
    const studentsById = {};
    students.forEach(s => {
      studentsById[s.studentId] = s;
    });

    const search = searchText.trim().toLowerCase();
    const bills = (allStudentBillings || []).map(item => {
      const isOther = !item.studentId;
      // the backend now sends name / admission no / class; the student list is only a fallback
      const student = !isOther ? studentsById[item.studentId] : null;
      const name = item.payerName || (student ? formStudentName(student) : '--');
      const reg = item.registerNumber || student?.registerNumber;
      const paid = item.status === 'PAID';
      return {
        ...item,
        isOther,
        paid,
        searchHay: [name, reg, item.payerPhone, item.billName].join(' ').toLowerCase(),
        payerCell: (
          <div>
            <b>{name}</b>
            <div style={subText}>
              {isOther
                ? `Other${item.payerPhone ? ` · ${item.payerPhone}` : ''}`
                : [reg, item.className].filter(Boolean).join(' · ') || '--'}
            </div>
          </div>
        ),
        billCell: (
          <div>
            {item.billName}
            {!!item.description && <div style={subText}>{item.description}</div>}
          </div>
        ),
        typeLabel: <BillTypeTag billType={item.billType} />,
        amountLabel: <b>{formatMoney(item.amount)}</b>,
        statusLabel: (
          <span style={{ fontWeight: 700, fontSize: 12, color: paid ? '#2e7d32' : '#b26a00' }}>
            {niceEnum(item.status)}
          </span>
        ),
        dueDateLabel: item.dueDate ? moment(item.dueDate).format('DD MMM, YYYY') : '--',
        receiptLabel: (
          <BillReceiptLinks billId={item.studentCustomBillId} status={item.status} schoolId={this.state.schoolId} />
        ),
      };
    });
    const filteredContent = bills.filter(
      item =>
        (!search || item.searchHay.includes(search)) &&
        (!filterPayer || (filterPayer === 'OTHER') === item.isOther) &&
        (!filterType || item.billType === filterType) &&
        (!filterStatus || (filterStatus === 'PAID') === item.paid)
    );
    const sum = list => list.reduce((total, item) => total + Number(item.amount || 0), 0);
    const typeOptions = [...new Set(bills.map(item => item.billType).filter(Boolean))].map(type => ({
      value: type,
      label: niceEnum(type),
    }));

    return (
      <div className="content">
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 12, marginBottom: 14, minHeight: 78 }}>
          <StatTile label="Bills" value={bills.length} tone="info" minWidth={150} maxWidth={240} />
          <StatTile label="Total billed" value={formatMoney(sum(bills))} tone="neutral" minWidth={150} maxWidth={240} />
          <StatTile
            label="Paid"
            value={formatMoney(sum(bills.filter(item => item.paid)))}
            tone="good"
            minWidth={150}
            maxWidth={240}
          />
          <StatTile
            label="Not paid yet"
            value={formatMoney(sum(bills.filter(item => !item.paid)))}
            tone={bills.some(item => !item.paid) ? 'warn' : 'good'}
            active={filterStatus === 'UNPAID'}
            onClick={
              bills.some(item => !item.paid)
                ? () => this.setState({ filterStatus: filterStatus === 'UNPAID' ? '' : 'UNPAID' })
                : undefined
            }
            note={
              bills.some(item => !item.paid)
                ? filterStatus === 'UNPAID'
                  ? 'Showing only these. Click to show all'
                  : 'Click to show these'
                : undefined
            }
            minWidth={150}
            maxWidth={240}
          />
        </div>
        <div className="rui-listbar" style={{ display: 'flex', alignItems: 'center', gap: 10, flexWrap: 'wrap' }}>
          <Input
            name="searchText"
            style={{ width: 300, height: 36, borderRadius: 12, fontSize: 13 }}
            placeholder="Search by name, admission no, mobile or bill..."
            value={searchText}
            onChange={e => this.setState({ searchText: e.target.value })}
          />
          <div style={{ width: 150 }}>
            <FilterSelect
              options={[
                { value: 'STUDENT', label: 'Students' },
                { value: 'OTHER', label: 'Others' },
              ]}
              value={filterPayer}
              placeholder="All payers"
              onChange={value => this.setState({ filterPayer: value })}
            />
          </div>
          <div style={{ width: 150 }}>
            <FilterSelect
              options={typeOptions}
              value={filterType}
              placeholder="All types"
              onChange={value => this.setState({ filterType: value })}
            />
          </div>
          <div style={{ width: 150 }}>
            <FilterSelect
              options={[
                { value: 'PAID', label: 'Paid' },
                { value: 'UNPAID', label: 'Not paid' },
              ]}
              value={filterStatus}
              placeholder="Any status"
              onChange={value => this.setState({ filterStatus: value })}
            />
          </div>
          <div style={{ marginLeft: 'auto' }}>
            <CustomButton
              name="+ Add Bill"
              onClick={this.openAddBill}
              style={{ backgroundColor: colors.accent, color: colors.white }}
            />
          </div>
        </div>
        <div className="rui-listarea">
          <MuiTable
            tableHeaders={tableHeaders}
            tableBodyData={{ content: filteredContent }}
            bodyColumns={bodyColumns}
            idName="studentCustomBillId"
            hidePagination
            isLoading={isFetching}
          />
        </div>
        <BillingFormModal
          isOpen={isModalOpen}
          onClose={this.closeModal}
          editingBill={editingBill}
          isSaving={isSaving}
          onCreate={this.submitCreateBill}
          onUpdate={this.submitUpdateBill}
          showWarning={this.showWarning}
          showStudentPicker
          studentOptions={studentOptions}
          isStudentsLoading={isStudentsFetching}
        />
      </div>
    );
  }
}

const mapStateToProps = state => {
  return {
    loggedUserToken: state.auth.loggedUserToken,
    loggedUserSchool: state.auth.loggedUserSchool,
    allStudentBillings: state.billing?.allStudentBillings,
  };
};

const mapDispatchToProps = dispatch => {
  return {
    fetchAllStudentBillings: data => dispatch(fetchAllStudentBillingsService(data)),
    createBilling: data => dispatch(addStudentBillingService(data)),
    updateBilling: data => dispatch(updateStudentBillingService(data)),
  };
};

export default connect(mapStateToProps, mapDispatchToProps)(BillingsPage);
