import React, { useEffect, useRef } from 'react';
import Select, { components } from 'react-select';
import { containWheel } from 'utils/useContainWheel';
import colors from 'config/colors';

// A searchable drop-down in the app's look (type to filter, so it keeps working when the list grows to hundreds).
// options: [{ value, label }]; value is the selected option's value ('' = nothing chosen, shows the placeholder).
const styles = {
  control: (base, state) => ({
    ...base,
    minHeight: 36,
    borderRadius: 12,
    fontSize: 13,
    borderColor: state.isFocused ? colors.accent : '#e8e3f0',
    boxShadow: 'none',
    '&:hover': { borderColor: colors.accent },
  }),
  valueContainer: base => ({ ...base, padding: '0 10px' }),
  option: (base, state) => ({
    ...base,
    fontSize: 13,
    cursor: 'pointer',
    color: state.isSelected ? '#fff' : '#1b1030',
    background: state.isSelected ? colors.accent : state.isFocused ? '#f1ecf7' : '#fff',
  }),
  menu: base => ({ ...base, borderRadius: 12, overflow: 'hidden', zIndex: 20 }),
  placeholder: base => ({ ...base, color: '#9ca3af' }),
  indicatorSeparator: () => ({ display: 'none' }),
};

// The page has its own wheel script, so without this the wheel over the open list scrolled the page behind it.
const MenuList = props => {
  const ref = useRef(null);
  useEffect(() => containWheel(ref.current));
  return (
    <components.MenuList
      {...props}
      innerRef={node => {
        ref.current = node;
        props.innerRef(node);
      }}
    />
  );
};

const FilterSelect = ({
  options,
  value,
  onChange,
  placeholder,
  searchable = true,
  clearable = true,
  formatOptionLabel,
}) => (
  <Select
    styles={styles}
    components={{ MenuList }}
    options={options}
    isSearchable={searchable}
    isClearable={clearable}
    placeholder={placeholder}
    formatOptionLabel={formatOptionLabel}
    noOptionsMessage={() => 'Nothing matches'}
    value={options.find(o => String(o.value) === String(value)) || null}
    onChange={option => onChange(option ? option.value : '')}
  />
);

export default FilterSelect;
